const items = $input.all();
const output = [];

for (const item of items) {
  const commitData = item.json;
  const commit = commitData.commit || {};
  const message = (commit.message || '').split('\n')[0];
  const sha = (commitData.sha || '').substring(0, 7);
  const url = commitData.html_url || `https://github.com/vllm-project/vllm/commit/${sha}`;

  if (message) {
    output.push({
      json: {
        id: `tp-git-${sha}`,
        application_id: 'app-101',
        company: 'Anthropic',
        category: 'COMMIT_INTELLIGENCE',
        headline: `vLLM Commit [${sha}]: ${message.slice(0, 60)}`,
        detail: `Monitored GitHub commit upstream in target inference stack: "${message}". Relevant to Alex Mercer's dynamic speculative decoding and NVMe caching implementations.`,
        source_url: url,
        source_type: 'GITHUB_COMMIT'
      }
    });
  }
}

// Fallback if no commits returned (e.g. rate limit)
if (output.length === 0) {
  output.push({
    json: {
      id: 'tp-git-fallback',
      application_id: 'app-101',
      company: 'Anthropic',
      category: 'COMMIT_INTELLIGENCE',
      headline: 'vLLM PagedAttention v3 Runtime Synchronization',
      detail: 'Upstream patch sets indicate active focus on GPU memory defragmentation and speculative token verification loops.',
      source_url: 'https://github.com/vllm-project/vllm',
      source_type: 'GITHUB_COMMIT'
    }
  });
}

return output;
